use crate::context::{Actor, Ports};
use crate::error::AppResult;
use crate::support::credentials::{confirm_password, mfa_not_enabled};
use crate::write_set::{Mutation, WriteSet};

use super::new_backup_codes;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackupCodeView {
    /// Plaintext, present only for codes generated by this call.
    pub code: Option<String>,
    pub consumed: bool,
}

/// Lists the backup codes' consumed state, or replaces them all (`regenerate`)
/// and returns the new plaintext once. Codes are hashed at rest, so a plain
/// listing cannot reveal them.
pub async fn execute(
    ports: &Ports,
    actor: &Actor,
    password: &str,
    regenerate: bool,
) -> AppResult<Vec<BackupCodeView>> {
    actor.require_user()?;
    let credentials = confirm_password(ports, actor.user_id, password).await?;
    if credentials.totp_secret.is_none() {
        return Err(mfa_not_enabled());
    }
    if !regenerate {
        let records = ports.users.backup_codes(actor.user_id).await?;
        return Ok(records
            .into_iter()
            .map(|record| BackupCodeView {
                code: None,
                consumed: record.consumed,
            })
            .collect());
    }
    let codes = new_backup_codes(ports).await?;
    let mut writes = WriteSet::new();
    writes.mutate(Mutation::ReplaceBackupCodes {
        user_id: actor.user_id,
        hashes: codes.hashes,
    });
    ports.unit_of_work.commit(writes).await?;
    Ok(codes
        .display
        .into_iter()
        .map(|code| BackupCodeView {
            code: Some(code),
            consumed: false,
        })
        .collect())
}
